      el.onerror = () => {
        if (cancelled) return;
        if (withCors) load(url, false);
        else errorRef.current?.();
      };
      el.src = url;
    };

    if (src) load(src, true);

    if (reduce) {
      repaint();
      return () => {
        cancelled = true;
        observer?.disconnect();
      };
    }

    let frameId = 0;
    let last = 0;
    let elapsed = 0;
    let eased = 0;
    let split = 0;
    let fired = false;
    let stopped = false;
    let visible = true;

    const tick = (now: number) => {
      frameId = requestAnimationFrame(tick);
      if (!last) last = now;
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;
      elapsed += dt;
      scene.clock = elapsed;

