99	/**
100	 * Screen two's backdrop: every kind of card the library makes, riding a tilted
101	 * ring around the copy. A blend of React Bits' Circular Carousel (the ring),
102	 * Infinite Spiral (depth scaling toward the viewer), Drift Wall (each card's
103	 * own slow bob) and Fancy's Parallax Floating (the pointer nudges near cards
104	 * more than far ones).
105	 *
106	 * One rAF loop writes transforms straight to the cards, so React renders this
107	 * once. The loop only lives while the screen is mounted; reduced motion gets a
108	 * single still frame.
109	 */
110	export function KeptOrbit() {
111	  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
112	
113	  // Layout effect, so the first painted frame already has every card on the ring.
114	  useLayoutEffect(() => {
115	    const pointer = { x: 0, y: 0 };
116	    const eased = { x: 0, y: 0 };
117	
118	    const place = (seconds: number) => {
119	      const turn = (seconds / LAP_SECONDS) * Math.PI * 2;
120	      eased.x += (pointer.x - eased.x) * 0.05;
121	      eased.y += (pointer.y - eased.y) * 0.05;
122	      CARDS.forEach((card, index) => {
123	        const el = cardRefs.current[index];
124	        if (!el) return;
125	        const angle = (index / CARDS.length) * Math.PI * 2 + turn;
126	        // depth: 1 at the front of the ring (bottom), 0 at the back (top)
127	        const depth = (Math.cos(angle) + 1) / 2;
128	        const bob = Math.sin(seconds * 0.6 + index * 1.7) * 5;
129	        const x = CENTER_X + Math.sin(angle) * RADIUS_X + eased.x * PARALLAX_PX * (0.4 + depth);
130	        const y =
131	          CENTER_Y + Math.cos(angle) * RADIUS_Y + bob + eased.y * PARALLAX_PX * (0.4 + depth);
132	        const scale = 0.7 + depth * 0.38;
133	        const tilt = Math.sin(angle) * -6;
134	        el.style.transform = `translate3d(${x - card.w / 2}px, ${y - card.h / 2}px, 0) scale(${scale}) rotate(${tilt}deg)`;
135	        el.style.opacity = String(0.38 + depth * 0.62);
136	        el.style.zIndex = String(Math.round(depth * 100));
137	      });
138	    };
139	
140	    if (prefersReducedMotion()) {
141	      place(0);
142	      return;
143	    }
144	
145	    const onPointerMove = (event: PointerEvent) => {
146	      pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
147	      pointer.y = (event.clientY / window.innerHeight) * 2 - 1;
148	    };
149	    window.addEventListener("pointermove", onPointerMove);
150	
151	    let raf = 0;
152	    let start = 0;
153	    const tick = (ms: number) => {
154	      raf = requestAnimationFrame(tick);
155	      if (!start) start = ms;
156	      place((ms - start) / 1000);
157	    };
158	    place(0);
159	    raf = requestAnimationFrame(tick);
160	    return () => {
161	      cancelAnimationFrame(raf);
162	      window.removeEventListener("pointermove", onPointerMove);
163	    };
164	  }, []);
165	
166	  return (
167	    <div className="kept-orbit" aria-hidden="true">
168	      {CARDS.map((card, index) => (
