import { useLayoutEffect, useRef } from "react";
import { prefersReducedMotion } from "../mascot/mascotStore";
import { onboardingPhotos } from "./onboardingMedia";

type Layer = "far" | "mid" | "near";
type FloatCard = { src: string; layer: Layer; x: number; y: number; w: number; h: number };

const p = onboardingPhotos;

// Positions and sizes come straight from the "Onboarding 2 · Every kind of
// thing" board in Paper, in the 960x540 stage's own pixels.
const CARDS: FloatCard[] = [
  { src: p.deskPlant, layer: "far", x: 10, y: 80, w: 71, h: 71 },
  { src: p.record, layer: "far", x: 870, y: 74, w: 71, h: 71 },
  { src: p.sprig, layer: "far", x: 411, y: 12, w: 58, h: 87 },
  { src: p.pottery, layer: "mid", x: 206, y: 396, w: 89, h: 89 },
  { src: p.field, layer: "mid", x: 110, y: 129, w: 110, h: 73 },
  { src: p.daisy, layer: "mid", x: 668, y: 52, w: 94, h: 85 },
  { src: p.delphinium, layer: "mid", x: 702, y: 395, w: 67, h: 120 },
  { src: p.sea, layer: "near", x: 753, y: 170, w: 134, h: 89 },
  { src: p.vases, layer: "near", x: 797, y: 302, w: 95, h: 126 },
  { src: p.book, layer: "near", x: 523, y: 435, w: 134, h: 89 },
  { src: p.stairs, layer: "near", x: 281, y: 401, w: 98, h: 122 },
  { src: p.monstera, layer: "near", x: 67, y: 232, w: 89, h: 134 },
  { src: p.sketching, layer: "near", x: 245, y: 20, w: 110, h: 110 },
  { src: p.car, layer: "near", x: 513, y: 28, w: 134, h: 89 },
];

/** How strongly each layer follows the pointer and drifts; near moves most. */
const DEPTH: Record<Layer, number> = { far: 0.3, mid: 0.6, near: 1 };
const PARALLAX_PX = 22;
const DRIFT_PX = 6;

/**
 * Screen two's backdrop: photos floating at three depths around the copy, as
 * on the Paper board. Fancy Components' Parallax Floating drives it: the
 * pointer pulls near photos further than far ones, and each photo drifts on
 * its own slow path, Drift Wall style.
 *
 * One rAF loop writes transforms straight to the photos, so React renders this
 * once. The loop only lives while the screen is mounted; reduced motion gets
 * the board's still layout.
 */
export function KeptFloating() {
  const cardRefs = useRef<(HTMLImageElement | null)[]>([]);

  useLayoutEffect(() => {
    if (prefersReducedMotion()) return;

    const pointer = { x: 0, y: 0 };
    const eased = { x: 0, y: 0 };
    const onPointerMove = (event: PointerEvent) => {
      pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
      pointer.y = (event.clientY / window.innerHeight) * 2 - 1;
    };
    window.addEventListener("pointermove", onPointerMove);

    let raf = 0;
    let start = 0;
    const tick = (ms: number) => {
      raf = requestAnimationFrame(tick);
      if (!start) start = ms;
      const seconds = (ms - start) / 1000;
      eased.x += (pointer.x - eased.x) * 0.06;
      eased.y += (pointer.y - eased.y) * 0.06;
      CARDS.forEach((card, index) => {
        const el = cardRefs.current[index];
        if (!el) return;
        const depth = DEPTH[card.layer];
        const driftX = Math.sin(seconds * 0.23 + index * 2.1) * DRIFT_PX * depth;
        const driftY = Math.cos(seconds * 0.31 + index * 1.3) * DRIFT_PX * depth;
        const x = driftX - eased.x * PARALLAX_PX * depth;
        const y = driftY - eased.y * PARALLAX_PX * depth;
        el.style.transform = `translate3d(${x}px, ${y}px, 0)`;
      });
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onPointerMove);
    };
  }, []);

  return (
    <div className="kept-floating" aria-hidden="true">
      {CARDS.map((card, index) => (
        <img
          key={card.src}
          ref={(el) => {
            cardRefs.current[index] = el;
          }}
          className={`kept-photo is-${card.layer}`}
          src={card.src}
          alt=""
          draggable={false}
          style={{ left: card.x, top: card.y, width: card.w, height: card.h }}
        />
      ))}
    </div>
  );
}

import { useEffect, useState } from "react";
import { prefersReducedMotion } from "../mascot/mascotStore";
import { onboardingPhotos } from "./onboardingMedia";

const QUERY = "lumen";
const TYPE_MS = 110;
const TYPE_START_MS = 700;
const FOUND_DELAY_MS = 280;

const LINES = [
  ["2 × galão", "3.40"],
  ["1 × pastel de nata", "1.30"],
  ["1 × água", "0.90"],
] as const;

/**
 * The "It reads your pictures, too." demo: one word typed into search, and the
 * receipt photo that mentions it coming into focus with the match marked.
 * Plays once per visit; reduced motion lands on the finished frame.
 */
export function ReadsPictures() {
  const [reduced] = useState(prefersReducedMotion);
  const [typed, setTyped] = useState(reduced ? QUERY.length : 0);
  const [found, setFound] = useState(reduced);

  useEffect(() => {
    if (found) return;
    if (typed >= QUERY.length) {
      const timer = window.setTimeout(() => setFound(true), FOUND_DELAY_MS);
      return () => window.clearTimeout(timer);
    }
    const timer = window.setTimeout(
      () => setTyped((count) => count + 1),
      typed === 0 ? TYPE_START_MS : TYPE_MS,
    );
    return () => window.clearTimeout(timer);
  }, [found, typed]);

  return (
    <div className={`reads-pictures${found ? " is-found" : ""}`} aria-hidden="true">
      <img
        className="reads-backdrop"
        src={onboardingPhotos.car}
        alt=""
        draggable={false}
        style={{ left: -10, top: 170 }}
      />
      <img
        className="reads-backdrop"
        src={onboardingPhotos.book}
        alt=""
        draggable={false}
        style={{ left: 318, top: 200 }}
      />
      <div className="reads-search">
        <span className="reads-eyes">
          <span />
          <span />
        </span>
        <span className="reads-query">{QUERY.slice(0, typed)}</span>
        <span className="reads-caret" />
      </div>
      <div className="reads-receipt">
        <span className="reads-receipt-kicker">— RECEIPT —</span>
        <span className="reads-receipt-name">
          <span className="reads-receipt-mark" />
          CAFÉ LUMEN
        </span>
        <span className="reads-receipt-kicker">Rua das Flores 28, Lisboa</span>
        <span className="reads-receipt-rule" />
        {LINES.map(([item, price]) => (
          <span key={item} className="reads-receipt-line">
            <span>{item}</span>
            <span>{price}</span>
          </span>
        ))}
        <span className="reads-receipt-rule" />
        <span className="reads-receipt-line is-total">
          <span>TOTAL</span>
          <span>€5.60</span>
        </span>
        <span className="reads-receipt-kicker is-footer">14 MAR 2026 · 09:12</span>
        <span className="reads-receipt-kicker">obrigado!</span>
      </div>
    </div>
  );
}

